frontend_call.options:
{
				method: "POST",
				headers,
				body: JSON.stringify({ session_id: sid }

{
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ text, engine, session_id: sid }

{
				method: "POST",
				headers: { "content-type": "application/json", ...authHeader() },
				body: JSON.stringify({
					capture: capturedElement,
					instruction,
					session_id: sessionId,
					task_id: taskId,
				}

{
			body: {
				prompt,
				session_id: sessionId,
				provider: apiKeyStore.provider,
				model: apiKeyStore.model.trim() || undefined,
				config: apiKeyStore.asConfig(),
			},
		}

{
			body: {
				doc: turn.requirementDoc,
				session_id: turn.sessionId,
				provider: apiKeyStore.provider,
				model: apiKeyStore.model.trim() || undefined,
				config: apiKeyStore.asConfig(),
			},
		}

{
			body: { manifest: turn.manifest, session_id: turn.sessionId, config: apiKeyStore.asConfig() },
		}

{
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({ repo_path: repoPath || null, branch: branch || null }

{
			method: "POST",
			body: {
				objective,
				provider: apiKeyStore.provider,
				model: apiKeyStore.model.trim() || apiKeyStore.current.defaultModel || undefined,
				workspace_id: botState?.workspace?.path || undefined,
				// Request-scoped provider config is consumed by MasterAgent and is
				// never persisted in task state or returned by this endpoint.
				config: apiKeyStore.asConfig(),
			},
		}

{
			method: "POST",
			body: { provider, model, workspace: workspace.trim() || undefined, credential_ref },
		}

{
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({
					text: "根据当前 git 变更写一条简洁的中文 commit message (一句话, 含类型前缀如 feat/fix/docs)。",
					engine: "master",
				}

{
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ message: commitMsg, files: picked }

{
				method: "POST",
				body: { runtime: selectedRuntime, task: taskText.trim() }
			}

{
				method: "POST",
				headers: { "content-type": "application/json", ...authHeader() },
				body: JSON.stringify({ request_id: req.request_id, approved }

{
			method: "POST",
			headers: { "content-type": "application/json", ...authHeader() },
			body: JSON.stringify({ request_id: q.request_id, answer }

{
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ session_id: sid, turn_id: activeTurnId ?? undefined }

{
		method: "POST",
		body: {
			endpoint: subscription.endpoint,
			keys: { p256dh: keys.p256dh ?? "", auth: keys.auth ?? "" },
		},
	}

{
      method: "POST",
      body: {
        goal: input.goal,
        supervision_mode: input.supervision_mode,
        workspace: input.workspace ?? "",
        executor: input.executor ?? "",
        acceptance_criteria: input.acceptance_criteria ?? [],
        constraints: input.constraints ?? [],
      },
    }
